import{_ as t,o as s,c as i,ag as a}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"Skill Definitions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/definitions.md","filePath":"en/modules/skills/definitions.md","lastUpdated":null}'),l={name:"en/modules/skills/definitions.md"};function d(o,e,n,c,r,h){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="skill-definitions" tabindex="-1">Skill Definitions <a class="header-anchor" href="#skill-definitions" aria-label="Permalink to &quot;Skill Definitions&quot;">​</a></h1><p>Skill files are stored under <code>skills/*.yml</code>. EmakiSkills defines management data while MythicMobs usually performs the actual effect.</p><p>Important fields include <code>id</code>, <code>enabled</code>, <code>display_name</code>, <code>mythic_skill</code>, <code>trigger_type</code>, <code>passive_triggers</code>, <code>cooldown_ticks</code>, <code>global_cooldown_ticks</code>, <code>resource_costs</code>, <code>upgrade</code>, and <code>condition</code>.</p><p>Equip-gating and GUI grouping fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>tags</code></td><td>Skill tag list, used for equip-count limits and category filtering together with <code>config.yml &gt; skill_tags.equip_limits</code>.</td></tr><tr><td><code>tab_tags</code></td><td>GUI tab tag list.</td></tr><tr><td><code>required_skills</code></td><td>Skill IDs that must already be equipped before this skill can be equipped. Alias: <code>dependencies</code>. Empty by default.</td></tr><tr><td><code>conflicting_skills</code></td><td>Skill IDs that cannot be equipped alongside this skill. Alias: <code>conflicts</code>. Empty by default.</td></tr><tr><td><code>show_in_slots</code></td><td>Whether the skill may appear in the player&#39;s active slot selection list. Equipment-forced trigger skills usually set this to <code>false</code>.</td></tr></tbody></table><h2 id="skill-sources-and-tag-limits" tabindex="-1">Skill sources and tag limits <a class="header-anchor" href="#skill-sources-and-tag-limits" aria-label="Permalink to &quot;Skill sources and tag limits&quot;">​</a></h2><p>Both blocks below live in <code>plugins/EmakiSkills/config.yml</code> and control how skills are recognized and how many can be equipped.</p><h3 id="equipment-skill-source-switches" tabindex="-1">Equipment skill source switches <a class="header-anchor" href="#equipment-skill-source-switches" aria-label="Permalink to &quot;Equipment skill source switches&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skill_sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  read_lore_skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  read_pdc_skills</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  require_lore_pdc_match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>read_lore_skills</code></td><td><code>true</code></td><td>Whether to read skills from equipment lore.</td></tr><tr><td><code>read_pdc_skills</code></td><td><code>true</code></td><td>Whether to read skills from equipment PDC.</td></tr><tr><td><code>require_lore_pdc_match</code></td><td><code>false</code></td><td>Strict mode. When enabled, only the lore∩PDC intersection for the same item and slot is kept; skills present on just one side do not apply.</td></tr></tbody></table><h3 id="tag-equip-limits" tabindex="-1">Tag equip limits <a class="header-anchor" href="#tag-equip-limits" aria-label="Permalink to &quot;Tag equip limits&quot;">​</a></h3><p>When a skill&#39;s <code>tags</code> match an entry here, a player may equip at most that many skills carrying the tag:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skill_tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  equip_limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    ultimate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    mobility</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span></code></pre></div><p>So at most one <code>ultimate</code> skill and two <code>mobility</code> skills can be equipped at the same time. Tags not listed here are unlimited.</p><h2 id="resource-cost-types" tabindex="-1">Resource cost types <a class="header-anchor" href="#resource-cost-types" aria-label="Permalink to &quot;Resource cost types&quot;">​</a></h2><p>Each <code>resource_costs</code> entry uses a <code>type</code> field:</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>ea-resource</code></td><td>Consume an EmakiAttribute resource.</td></tr><tr><td><code>attribute-check</code></td><td>Check an attribute value. Alias: <code>ea-attribute-check</code>.</td></tr><tr><td><code>local-resource</code></td><td>Use an EmakiSkills local resource definition.</td></tr><tr><td><code>auraskills-mana</code></td><td>Use AuraSkills mana. Aliases: <code>aura-skills-mana</code>, <code>aura-mana</code>.</td></tr><tr><td><code>mythiclib-mana</code></td><td>Use MythicLib / MMOCore mana. Aliases: <code>mmocore-mana</code>, <code>mythic-mana</code>.</td></tr></tbody></table><p><code>operation</code> accepts <code>consume</code> (deduct) or <code>require</code> (check only). <code>auraskills-mana</code> requires AuraSkills and <code>mythiclib-mana</code> requires MythicLib or MMOCore; the entry is treated as unavailable when the plugin is absent.</p>`,18)])])}const u=t(l,[["render",d]]);export{k as __pageData,u as default};
